import { dirname } from "node:path";
const here = dirname(import.meta.url);
function frames(error) {
  return String(error.stack)
    .split("\n")
    .filter((line) => line.includes(here))
    .map((line) => line.trim().split(`${here}/`).join(""))
    .join(" | ");
}
let first;
export async function load() {
  try {
    await import("./bad.mjs");
    return "loaded";
  } catch (error) {
    const same = first === error;
    first ??= error;
    return `${error.name}: ${error.message} [${frames(error)}] same=${same}`;
  }
}
